# -*- coding: utf-8 -*-
TIER2_HEAD = '<b>【 แบบที่ 2 ▸ พื้นฐาน · กระชับ · ตั้งสองสมการมุมเงยแล้วกำจัดระยะฐาน (two elevation equations, eliminate the base) 】</b>'
TIER2 = [
    '🎯 <b>เหมาะกับ</b> เด็กปานกลางถึงเก่ง · ตั้งความสูงอาคารกับระยะแนวราบเป็นตัวแปร เขียนสมการมุมเงยสองบรรทัด แล้วกำจัดระยะแนวราบทิ้ง',
    '<b>ขั้นที่ 1:</b> ให้ความสูงอาคารเป็น $H$ เมตร และระยะแนวราบจากจุด $P$ ถึงฐานอาคารเป็น $d$ เมตร',
    '⇒ โคนเสาอยู่ระดับเดียวกับขอบดาดฟ้า ⇒ ฐานอาคาร ขอบดาดฟ้า และยอดเสาอยู่บนเส้นดิ่งเส้นเดียวกัน ⇒ ยอดเสาสูงจากพื้น $H + 12$ เมตร และสามเหลี่ยมมุมฉากทั้งสองรูปใช้ระยะแนวราบ $d$ ร่วมกัน',
    '<b>ขั้นที่ 2:</b> ใช้ $\\tan(\\text{มุมเงย}) = \\dfrac{\\text{ความสูงของจุดที่เล็ง}}{\\text{ระยะแนวราบ}}$ กับมุมเงย $30^\\circ$ ที่เล็งขอบดาดฟ้า',
    '⇒ $\\tan 30^\\circ = \\dfrac{H}{d}$ ⇒ $\\dfrac{1}{\\sqrt{3}} = \\dfrac{H}{d}$ ⇒ คูณไขว้ ⇒ $d = H\\sqrt{3}$',
    '<b>ขั้นที่ 3:</b> ใช้สูตรเดิมกับมุมเงย $45^\\circ$ ที่เล็งยอดเสา โดยระยะแนวราบยังเป็น $d$ ตัวเดิม',
    '⇒ $\\tan 45^\\circ = \\dfrac{H + 12}{d}$ ⇒ $1 = \\dfrac{H + 12}{d}$ ⇒ $d = H + 12$',
    '<b>ขั้นที่ 4:</b> แทน $d = H\\sqrt{3}$ ลงในสมการของขั้นที่ 3 เพื่อให้เหลือตัวไม่รู้ตัวเดียว',
    '⇒ $H\\sqrt{3} = H + 12$ ⇒ $H\\sqrt{3} - H = 12$ ⇒ $H\\left(\\sqrt{3} - 1\\right) = 12$ ⇒ $H = \\dfrac{12}{\\sqrt{3} - 1}$',
    '<b>ขั้นที่ 5:</b> คูณสังยุค $\\dfrac{\\sqrt{3} + 1}{\\sqrt{3} + 1}$ ทั้งเศษและส่วน เพื่อทำตัวส่วนให้พ้นกรณฑ์',
    '⇒ $H = \\dfrac{12\\left(\\sqrt{3} + 1\\right)}{\\left(\\sqrt{3} - 1\\right)\\left(\\sqrt{3} + 1\\right)} = \\dfrac{12\\left(\\sqrt{3} + 1\\right)}{3 - 1} = \\dfrac{12\\left(\\sqrt{3} + 1\\right)}{2} = 6\\sqrt{3} + 6$ เมตร',
]
TIER3_HEAD = '<b>【 แบบที่ 3 ▸ ⚡ ประยุกต์ · สูตรผลต่างแทนเจนต์ (tangent-difference formula) 】</b>'
TIER3 = [
    '⚡ <b>เหมาะกับ</b> เด็กที่พื้นฐานคณิตดี มองออกว่าเสายาว $12$ เมตรคือส่วนสูงที่ถูกหนีบอยู่ระหว่างแนวสายตาสองเส้นพอดี จึงคว้าระยะแนวราบมาเป็นค่าจริงได้ในบรรทัดเดียว',
    '<b>ขั้นที่ 1:</b> ให้ $d$ เป็นระยะแนวราบจากจุด $P$ ถึงอาคาร · ยืนที่เดิมแล้วเล็งสองจุดบนเส้นดิ่งเส้นเดียวกันด้วยมุมเงย $\\alpha$ กับ $\\beta$ เมื่อ $\\beta > \\alpha$',
    '⇒ ความสูงของสองจุดนั้นคือ $d\\tan\\beta$ กับ $d\\tan\\alpha$ ⇒ ส่วนสูงที่คั่นอยู่ระหว่างจุดทั้งสองเท่ากับ $L = d\\left(\\tan\\beta - \\tan\\alpha\\right)$',
    '<b>ขั้นที่ 2:</b> แทน $L = 12$ , $\\beta = 45^\\circ$ , $\\alpha = 30^\\circ$ แล้วแก้หา $d$',
    '⇒ $12 = d\\left(\\tan 45^\\circ - \\tan 30^\\circ\\right) = d\\left(1 - \\dfrac{1}{\\sqrt{3}}\\right)$ ⇒ $d = \\dfrac{12}{1 - \\dfrac{1}{\\sqrt{3}}} = \\dfrac{12\\sqrt{3}}{\\sqrt{3} - 1}$',
    '<b>ขั้นที่ 3:</b> ความสูงอาคารคือความสูงของจุดล่างที่ถูกเล็งด้วยมุม $30^\\circ$ ⇒ คูณ $d$ ด้วย $\\tan 30^\\circ$ ได้ทันที',
    '⇒ $H = d\\tan 30^\\circ = \\dfrac{12\\sqrt{3}}{\\sqrt{3} - 1} \\cdot \\dfrac{1}{\\sqrt{3}} = \\dfrac{12}{\\sqrt{3} - 1} = \\dfrac{12\\left(\\sqrt{3} + 1\\right)}{2} = 6\\sqrt{3} + 6$ เมตร',
    '<b>ข้อต่าง:</b> เป็น<b>รูปสำเร็จ</b>ของการกำจัด $H$ ที่แบบที่ 1–2 ต้องทำสดทุกครั้ง ⇒ จำ $L = d\\left(\\tan\\beta - \\tan\\alpha\\right)$ ได้ ก็เหลือตัวไม่รู้ตัวเดียวคือ $d$ ตั้งแต่บรรทัดแรก ⛔ พูดให้ตรง : เนื้อในยังเป็นสมการสองสมการชุดเดิม เพียงกำจัด $H$ ด้วยการ<b>ลบ</b>แทนการแทนค่า และสิ่งที่ใช้คือ<b>ผลต่างของแทนเจนต์สองตัว</b> ⛔ ไม่ใช่ $\\tan\\left(\\beta - \\alpha\\right)$ ⇒ ที่ได้จริงคือความยาวเสา $12$ ถูกใช้เป็นก้อนเดียว ไม่ต้องเขียนความสูงยอดเสาเป็น $H + 12$',
]
